INSERT OR IGNORE INTO spots (id, name, aliases, lat, lon, country, sports, kind, launch_notes, status, facing_source, sources, submissions) VALUES ('kite-surf-center-iko-k1-osm-7545810612', 'Kite surf center IKO K1', 'kite surf center iko k1|кайт серф центр iko k1 - межводное|кайт серф центр iko k1 - міжводне|kite center windextreme mezhvodnoe, iko', 45.55739, 32.83304, '', 'kitesurf|wingfoil', 'school', 'Уроки кайт-серфинга на пустом, частном пляже. Команда инструкторов с лицензией международной организации кайтсерфинга IKO. Выдаем официальные лицензии кайтеров. Учим на качественном новом снаряжении. Доступны услуги хранения и проката снаряжения. | web: https://k1.surf/', 'seed', 'seed', 'https://www.openstreetmap.org/node/7545810612', 0);
